<script setup lang="ts">
import FieldError from '../FleetAndDocuments/components/FieldError.vue';
import {computed,onMounted,onBeforeUnmount,ref,watch,useId} from 'vue';
import {request as fetchRaw} from '../Workshop/api';
const controller=new AbortController();
onBeforeUnmount(()=>controller.abort());
const raw:typeof fetchRaw=(path,method='GET',body,signal)=>fetchRaw(path,method,body,method==='GET'?signal??controller.signal:signal);
import SearchSelect from '../Workshop/components/SearchSelect.vue';
import {instant,localInstant} from '../Workshop/presentation';
import {registrationDate} from '../FleetAndDocuments/presentation';
interface Stock {spare_part_id:string;code:string;description:string;unit:string;initialized:boolean;available_quantity:string|null;custody_quantity:string|null;consumed_quantity:string|null}
interface Custody {delivery_id:string;mechanic_assignment_id:string;work_order_id:string;spare_part_id:string;unit_snapshot:string;employee_id:string;employee_name?:string;part_code?:string;part_description?:string;held_quantity:string;consumed_quantity:string}
interface Correction {id:string;spare_part_id:string;kind:string;quantity:string;reason:string;decision_id:string|null;decision:string|null;application_id:string|null}
interface Movement {id:string;spare_part_id:string;kind:string;warehouse_delta:string;custody_delta:string;consumed_delta:string;occurred_at:string;actor_id:string|number;actor_name?:string;delivery_id?:string|null}
const props=defineProps<{admin:boolean;office:boolean;busy:boolean;epoch:number;errors:Record<string,string[]>}>();
const emit=defineEmits<{command:[title:string,path:string,body:Record<string,unknown>];error:[error:unknown];clearErrors:[]}>();
const stock=ref<Stock[]>([]),custody=ref<Custody[]>([]),corrections=ref<Correction[]>([]),movements=ref<Movement[]>([]),loading=ref(false),search=ref('');
const mode=ref(''),part=ref(''),quantity=ref(''),reason=ref(''),at=ref(localInstant()),kind=ref('initial'),movement=ref(''),decision=ref('approved'),selected=ref<Custody|null>(null),correction=ref<Correction|null>(null);
const options=computed(()=>stock.value.map(s=>({value:s.spare_part_id,label:`${s.code} · ${s.description} · ${s.unit}`}))),visible=computed(()=>stock.value.filter(s=>`${s.code} ${s.description}`.toLowerCase().includes(search.value.toLowerCase())));
const movementOptions=computed(()=>movements.value.map(m=>({value:m.id,label:`${label(m.spare_part_id)} · ${kinds[m.kind]??m.kind} · ${m.warehouse_delta} bodega / ${m.custody_delta} custodia / ${m.consumed_delta} consumido · ${registrationDate(m.occurred_at)}`})));
const kinds:Record<string,string>={initial:'Conciliación inicial',adjustment:'Ajuste',reversal:'Reversión',receipt:'Recepción',delivery:'Entrega',usage:'Consumo / rectificación',return:'Devolución'};
function label(id:string):string{return stock.value.find(s=>s.spare_part_id===id)?.code??id;}
async function rows<T>(path:string):Promise<T[]>{const values:T[]=[];for(let page=1;;page++){const v=await raw(`${path}?per_page=100&page=${page}`) as {data:T[];meta?:{last_page:number};last_page?:number};if(!Array.isArray(v.data))throw new Error('Respuesta inválida');values.push(...v.data);if(page>=(v.meta?.last_page??v.last_page??1))return values;}}
let generation=0;onBeforeUnmount(()=>generation++);
async function load():Promise<void>{const run=++generation;loading.value=true;try{const [s,c]=await Promise.all([props.office?rows<Stock>('/inventory/stock'):Promise.resolve([]),rows<Custody>('/inventory/custody')]);if(run!==generation)return;stock.value=s;custody.value=c;if(props.office){const [m,r]=await Promise.all([rows<Movement>('/inventory/movements'),rows<Correction>('/inventory/corrections')]);if(run!==generation)return;movements.value=m;corrections.value=r;}}catch(e){if(run===generation)emit('error',e);}finally{if(run===generation)loading.value=false;}}
function begin(action:string,c?:Custody,r?:Correction):void{emit('clearErrors');mode.value=action;selected.value=c??null;correction.value=r??null;quantity.value='';reason.value='';at.value=localInstant();}
function submit():void{if(props.busy)return;const common={quantity:quantity.value,reason:reason.value,occurred_at:instant(at.value)};if(mode.value==='correction')emit('command','Solicitar conciliación o ajuste','/inventory/corrections',{...common,spare_part_id:part.value,kind:kind.value,unit_snapshot:stock.value.find(s=>s.spare_part_id===part.value)?.unit,...(kind.value==='reversal'?{reverses_movement_id:movement.value}:{})});if(mode.value==='return'&&selected.value)emit('command','Confirmar devolución física en bodega','/inventory/returns',{...common,delivery_id:selected.value.delivery_id});if(mode.value==='use'&&selected.value)emit('command','Confirmar utilización real',`/workshop/orders/${selected.value.work_order_id}/usages`,{...common,delivery_id:selected.value.delivery_id,mechanic_assignment_id:selected.value.mechanic_assignment_id});if(mode.value==='decision'&&correction.value)emit('command','Decidir corrección de inventario',`/inventory/corrections/${correction.value.id}/decisions`,{decision:decision.value,reason:reason.value,occurred_at:instant(at.value)});}
function apply(r:Correction):void{if(!r.decision_id)return;emit('command','Aplicar corrección autorizada',`/inventory/decisions/${r.decision_id}/apply`,{occurred_at:instant(localInstant())});}
watch(()=>props.epoch,()=>{mode.value='';void load();});onMounted(load);
const errorId=useId();
</script>
<template><section class="space-y-5"><div class="flex flex-wrap gap-3"><button class="btn-secondary" :disabled="busy||loading" @click="load">Actualizar inventario</button><button v-if="office" class="btn-primary" :disabled="busy||loading" @click="begin('correction')">Solicitar conciliación o ajuste</button><a class="btn-secondary" href="/taller">Entregar repuestos en órdenes de Taller</a></div><p class="notice-info">Las entregas pasan de bodega a responsabilidad del mecánico. Solo el uso real confirmado se contabiliza como consumo. La devolución exige recepción física.</p><p v-if="loading" role="status">Consultando inventario…</p>
<form v-if="mode" class="panel space-y-3" :aria-label="mode==='return'?'Devolución física':mode==='use'?'Uso real':'Corrección de inventario'" @submit.prevent="submit"><fieldset :disabled="busy||loading" class="space-y-3"><h2 class="font-semibold">{{mode==='return'?'Recibir devolución en bodega':mode==='use'?'Confirmar repuestos utilizados':mode==='decision'?'Decisión administrativa':'Conciliación, ajuste o reversión'}}</h2><template v-if="mode==='correction'"><SearchSelect v-model="part" label="Repuesto" :options="options" required/><label>Tipo de corrección<select aria-label="Tipo de corrección" v-model="kind" class="field"><option value="initial">Conciliación física inicial</option><option value="adjustment">Ajuste autorizado</option><option value="reversal">Reversión compensatoria</option></select></label><SearchSelect v-if="kind==='reversal'" v-model="movement" label="Movimiento a revertir" :options="movementOptions" required/><p>Registra cantidades contadas físicamente. En ajustes, indica la diferencia con su signo; no una existencia inventada.</p></template><template v-if="selected"><p>{{selected.part_code??label(selected.spare_part_id)}} · {{selected.part_description}} · Orden {{selected.work_order_id}} · Mecánico {{selected.employee_name??selected.employee_id}} · Bajo responsabilidad: {{selected.held_quantity}} {{selected.unit_snapshot}}</p></template><template v-if="mode==='decision'"><p>{{correction?.kind}} · {{correction?.quantity}} · {{correction?.reason}}</p><label>Decisión<select aria-label="Decisión" v-model="decision" class="field"><option value="approved">Aprobar</option><option value="rejected">Rechazar</option></select></label></template><label v-else>Cantidad<input v-model="quantity" aria-label="Cantidad" class="field" required inputmode="decimal" :aria-invalid="!!errors['quantity']?.length" :aria-describedby="errors['quantity']?.length ? `${errorId}-quantity-error` : undefined"></label><FieldError :id="`${errorId}-quantity-error`" :errors="errors['quantity']"/><label>Fecha de operación<input v-model="at" aria-label="Fecha de operación" class="field" type="datetime-local" required :aria-invalid="!!errors['occurred_at']?.length" :aria-describedby="errors['occurred_at']?.length ? `${errorId}-at-error` : undefined"></label><FieldError :id="`${errorId}-at-error`" :errors="errors['occurred_at']"/><label>Motivo<textarea aria-label="Motivo" v-model="reason" class="field" required maxlength="2000" :aria-invalid="!!errors['reason']?.length" :aria-describedby="errors['reason']?.length ? `${errorId}-reason-error` : undefined"/></label><FieldError :id="`${errorId}-reason-error`" :errors="errors['reason']"/><button class="btn-primary">{{mode==='return'?'Confirmar recepción de devolución':mode==='use'?'Confirmar uso real':'Guardar operación'}}</button> <button type="button" class="btn-secondary" @click="mode=''">Cancelar</button></fieldset></form>
<section v-if="office" class="panel"><h2 class="font-semibold">Existencias reales</h2><label>Buscar repuestos<input v-model="search" aria-label="Buscar repuestos" class="field" type="search"></label><div class="overflow-x-auto"><table class="data-table"><thead><tr><th>Repuesto</th><th>Conciliado</th><th>Disponible en bodega</th><th>Bajo responsabilidad</th><th>Consumido</th></tr></thead><tbody><tr v-for="s in visible" :key="s.spare_part_id"><td>{{s.code}} · {{s.description}} · {{s.unit}}</td><td>{{s.initialized?'Sí':'Pendiente de conciliación'}}</td><td>{{s.initialized?s.available_quantity:'Sin existencia confirmada'}}</td><td>{{s.initialized?s.custody_quantity:'Sin conciliar'}}</td><td>{{s.initialized?s.consumed_quantity:'Sin conciliar'}}</td></tr></tbody></table></div></section>
<section class="panel"><h2 class="font-semibold">Entregas bajo responsabilidad</h2><div v-for="c in custody" :key="c.delivery_id" class="border-b border-blue-200 py-3 space-y-2"><p>{{c.part_code??label(c.spare_part_id)}} · {{c.part_description}} · Orden {{c.work_order_id}} · Mecánico {{c.employee_name??c.employee_id}}</p><p>Bajo responsabilidad {{c.held_quantity}} · Consumido {{c.consumed_quantity}} {{c.unit_snapshot}}</p><button v-if="!office||admin" class="btn-primary" :disabled="busy||loading" @click="begin('use',c)">Registrar utilización</button> <button v-if="office" class="btn-secondary" :disabled="busy||loading" @click="begin('return',c)">Recibir devolución física</button></div><p v-if="!custody.length">Sin entregas bajo responsabilidad.</p></section>
<section v-if="office" class="panel"><h2 class="font-semibold">Correcciones y autorizaciones</h2><article v-for="r in corrections" :key="r.id" class="border-b border-blue-200 py-3"><p>{{label(r.spare_part_id)}} · {{r.kind}} · {{r.quantity}} · {{r.reason}}</p><p>{{r.application_id?'Aplicada':r.decision??'Pendiente de decisión'}}</p><button v-if="admin&&!r.decision" class="btn-secondary" :disabled="busy||loading" @click="begin('decision',undefined,r)">Decidir corrección</button><button v-if="admin&&r.decision==='approved'&&!r.application_id" class="btn-primary" :disabled="busy||loading" @click="apply(r)">Aplicar corrección autorizada</button></article></section>
<section v-if="office" class="panel"><h2 class="font-semibold">Historial inmutable de movimientos</h2><div class="overflow-x-auto"><table class="data-table"><thead><tr><th>Repuesto</th><th>Operación</th><th>Cantidad</th><th>Fecha</th><th>Responsable y origen</th></tr></thead><tbody><tr v-for="m in movements" :key="m.id"><td>{{label(m.spare_part_id)}}</td><td>{{kinds[m.kind]??m.kind}}</td><td>Bodega {{m.warehouse_delta}} · Custodia {{m.custody_delta}} · Consumo {{m.consumed_delta}}</td><td>{{registrationDate(m.occurred_at)}}</td><td>{{m.actor_name??m.actor_id}} · {{m.delivery_id??m.id}}</td></tr></tbody></table></div></section></section></template>
